register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
  const resolved = this.resolveDefinition(definition);

  if (typeof definition !== 'function') {
    try {
      const validate = (this.ajv as any).compile(resolved.inputSchema);
      if (validate) {
        this.validatorCache.set(resolved.inputSchema, validate);
      }
    } catch (error) {
      throw new Error(
        `Failed to compile schema for tool ${resolved.name}: ${error instanceof Error ? error.message : String(error)}`,
        {cause: error}
      );
    }
  }

  this.tools.set(resolved.name, {definitionSource: definition, execute});
}

